// CPL News tab — renderer.
//
// STATIC consumer asset (NOT regenerated by excel_to_dashboard.py), lazy-loaded
// by the inline boot in the tab shell on first activation of #tab-cpl-news.
// Reads public.cpl_news LIVE from Supabase (anon key, public READ) — there is
// NO committed data artifact, so the feed is always as fresh as the last harvest
// (the cpl-news-harvest Edge Function, run by .github/workflows/cpl-news.yml).
//
// CA-first ordering (Sam's priority: California CPL first, national second);
// filters by scope / source type / related system + free-text search; a
// "suggest a story" box that writes to cpl_news_requests (the path closed
// socials enter); and reviewer feature/hide via the shared cpl_sb magic-link
// session (RLS gates the writes — is_allowed_reviewer()).
//
// Self-contained behind the CONFIG block (the cpl_chat.js pattern). Scoped CSS
// injected from JS so both HTMLs are covered without a Rule-4 mirror.
(function () {
  "use strict";

  // ── Config (anon key is public + RLS-gated; mirrors cpl_chat.js) ──
  var SUPABASE_URL = "https://hvuwhnbuahrtptokpqfh.supabase.co";
  var SUPABASE_ANON = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imh2dXdobmJ1YWhydHB0b2twcWZoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzU1NzI0ODEsImV4cCI6MjA5MTE0ODQ4MX0.p0q-93iTM0GkF2z8_q7Vvl1tsX9SFGMM-W7Wdx7WfmM";
  var REST = SUPABASE_URL + "/rest/v1";

  var SOURCE_TYPES = {
    news: { label: "News", icon: "📰" },
    official: { label: "Official", icon: "🏛️" },
    social: { label: "Social", icon: "💬" },
    budget: { label: "Budget", icon: "💰" },
    manual: { label: "Submitted", icon: "🔗" },
  };

  var CSS_ID = "cpl-news-css";
  var CSS = [
    ".cplnews { max-width: 1000px; margin: 0 auto; color: var(--text-body); }",
    ".cplnews h2 { color: var(--navy-primary); margin: 16px 0 4px; }",
    ".cplnews-intro { color: var(--text-muted); max-width: 820px; margin: 0 0 14px; font-size: .92rem; }",
    ".cplnews-intro .draftchip { display:inline-block; margin-left:8px; background: var(--mustard-fill, #f2dca0); color: var(--text-strong, #4a3a00); font-size:.62rem; font-weight:700; letter-spacing:.08em; padding:2px 8px; border-radius:10px; text-transform:uppercase; vertical-align:middle; }",
    ".cplnews-toolbar { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin:0 0 12px; }",
    ".cplnews-toolbar input.q { flex:1 1 220px; min-width:180px; padding:8px 12px; border:1px solid var(--border-strong); border-radius:6px; font-size:.9rem; }",
    ".cplnews-toolbar input.q:focus { outline:none; border-color: var(--navy-secondary); }",
    ".cplnews-seg { display:inline-flex; border:1px solid var(--border-strong); border-radius:6px; overflow:hidden; }",
    ".cplnews-seg button { background: var(--surface-opaque); color: var(--text-body); border:none; padding:7px 11px; font-size:.82rem; cursor:pointer; }",
    ".cplnews-seg button + button { border-left:1px solid var(--border-strong); }",
    ".cplnews-seg button.on { background: var(--navy-primary); color:#fff; font-weight:600; }",
    ".cplnews-select { padding:7px 10px; border:1px solid var(--border-strong); border-radius:6px; font-size:.82rem; background: var(--surface-opaque); color: var(--text-body); }",
    ".cplnews-count { font-size:.82rem; color: var(--text-muted); margin-left:auto; }",
    ".cplnews-list { display:flex; flex-direction:column; gap:10px; }",
    ".cplnews-card { border:1px solid var(--border); border-left:4px solid var(--border-strong); border-radius:8px; background: var(--surface-opaque); padding:12px 14px; }",
    ".cplnews-card.ca { border-left-color: var(--gold-accent, #C9A227); }",
    ".cplnews-card.featured { background: var(--surface-subtle); border-left-color: var(--navy-primary); }",
    ".cplnews-card.hidden { opacity:.5; }",
    ".cplnews-card .top { display:flex; flex-wrap:wrap; gap:6px; align-items:center; font-size:.74rem; color: var(--text-faint); margin-bottom:4px; }",
    ".cplnews-card .top .badge { font-weight:700; letter-spacing:.04em; padding:1px 7px; border-radius:10px; text-transform:uppercase; font-size:.64rem; }",
    ".cplnews-card .top .badge.ca { background: var(--gold-accent, #C9A227); color:#1c1c1a; }",
    ".cplnews-card .top .badge.national { background: var(--surface-muted); color: var(--text-muted); }",
    ".cplnews-card .top .sys { color: var(--navy-secondary); font-weight:600; }",
    ".cplnews-card h3 { margin:2px 0 4px; font-size:1.02rem; line-height:1.35; }",
    ".cplnews-card h3 a { color: var(--navy-primary); text-decoration:none; }",
    ".cplnews-card h3 a:hover { text-decoration:underline; }",
    ".cplnews-card .sum { font-size:.9rem; color: var(--text-body); margin:0 0 6px; }",
    ".cplnews-card .chips { display:flex; flex-wrap:wrap; gap:5px; }",
    ".cplnews-card .chip { font-size:.7rem; background: var(--surface-muted); color: var(--text-muted); border-radius:10px; padding:1px 8px; }",
    ".cplnews-card .star { color: var(--gold-accent, #C9A227); }",
    ".cplnews-rev { display:flex; gap:8px; margin-top:8px; padding-top:7px; border-top:1px dashed var(--border); font-size:.78rem; }",
    ".cplnews-rev button { background: var(--surface-subtle); border:1px solid var(--border-strong); border-radius:5px; padding:3px 9px; cursor:pointer; color: var(--text-body); }",
    ".cplnews-rev button:hover { background: var(--surface-muted); }",
    ".cplnews-empty { border:1px dashed var(--border-strong); border-radius:8px; background: var(--surface-subtle); color: var(--text-muted); padding:26px; text-align:center; }",
    ".cplnews-suggest { margin:18px 0 6px; border:1px solid var(--border); border-radius:8px; background: var(--surface-subtle); padding:12px 14px; }",
    ".cplnews-suggest h4 { margin:0 0 4px; color: var(--navy-primary); font-size:.95rem; }",
    ".cplnews-suggest p { margin:0 0 8px; font-size:.82rem; color: var(--text-muted); }",
    ".cplnews-suggest .row { display:flex; flex-wrap:wrap; gap:8px; }",
    ".cplnews-suggest input { flex:1 1 200px; padding:8px 11px; border:1px solid var(--border-strong); border-radius:6px; font-size:.85rem; }",
    ".cplnews-suggest button { background: var(--navy-primary); color:#fff; border:none; border-radius:6px; padding:8px 16px; font-weight:600; cursor:pointer; }",
    ".cplnews-suggest .msg { font-size:.8rem; margin-top:6px; min-height:16px; }",
    ".cplnews-suggest .msg.ok { color: var(--green-progress, #2e7d32); }",
    ".cplnews-suggest .msg.err { color: var(--red-alert, #b3261e); }",
    ".cplnews-foot { font-size:.76rem; color: var(--text-faint); margin:14px 2px 0; }",
    ".cplnews-signin { font-size:.78rem; color: var(--text-muted); }",
    ".cplnews-signin a { color: var(--accent-link, #1565a0); cursor:pointer; }",
  ].join("\n");

  function ensureCss() {
    if (document.getElementById(CSS_ID)) return;
    var s = document.createElement("style");
    s.id = CSS_ID;
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  // ── DOM helper ──
  function el(tag, attrs, kids) {
    var n = document.createElement(tag);
    if (attrs) {
      for (var k in attrs) {
        if (k === "style") { for (var s in attrs.style) n.style[s] = attrs.style[s]; }
        else if (k.indexOf("on") === 0 && typeof attrs[k] === "function") { n.addEventListener(k.slice(2), attrs[k]); }
        else if (k === "className") { n.className = attrs[k]; }
        else if (k === "html") { n.innerHTML = attrs[k]; }
        else if (attrs[k] != null) { n.setAttribute(k, attrs[k]); }
      }
    }
    if (kids != null) {
      if (!Array.isArray(kids)) kids = [kids];
      kids.forEach(function (c) {
        if (c == null) return;
        if (typeof c === "string") n.appendChild(document.createTextNode(c));
        else if (c instanceof Node) n.appendChild(c);
      });
    }
    return n;
  }

  function escapeHtml(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function fmtDate(iso) {
    if (!iso) return "";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    try {
      return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
    } catch (e) { return iso.slice(0, 10); }
  }

  // ── Shared magic-link session (cpl_sb), reused across curator tabs ──
  function getSession() {
    try {
      var s = JSON.parse(sessionStorage.getItem("cpl_sb") || "null");
      if (s && typeof s.access_token === "string") return s;
    } catch (e) {}
    return null;
  }
  function captureHash() {
    // If we landed from a magic link, persist the token (idempotent with the
    // other curator tabs that also capture it).
    try {
      var h = location.hash || "";
      if (h.indexOf("access_token=") === -1) return;
      var p = new URLSearchParams(h.replace(/^#/, ""));
      var at = p.get("access_token");
      if (!at) return;
      var sess = {
        access_token: at,
        refresh_token: p.get("refresh_token") || "",
        email: "",
      };
      try {
        var payload = JSON.parse(atob(at.split(".")[1].replace(/-/g, "+").replace(/_/g, "/")));
        sess.email = payload.email || "";
      } catch (e) {}
      sessionStorage.setItem("cpl_sb", JSON.stringify(sess));
      history.replaceState(null, "", location.pathname + location.search + "#cpl-news");
      try { window.dispatchEvent(new Event("cpl-auth-change")); } catch (e) {}
    } catch (e) {}
  }
  function isReviewer() { return !!getSession(); }

  function signIn() {
    var email = window.prompt("Reviewer sign-in — enter your @ email for a magic link:");
    if (!email) return;
    var redirect = encodeURIComponent(location.origin + location.pathname + "#cpl-news");
    fetch(REST.replace("/rest/v1", "") + "/auth/v1/otp?redirect_to=" + redirect, {
      method: "POST",
      headers: { apikey: SUPABASE_ANON, "Content-Type": "application/json" },
      body: JSON.stringify({ email: email, create_user: false }),
    }).then(function (r) {
      window.alert(r.ok ? "Check your email for the magic link." : "Sign-in failed (are you an allowed reviewer?).");
    }).catch(function () { window.alert("Sign-in request failed."); });
  }

  // ── Data ──
  var STATE = { rows: [], scope: "all", stype: "all", q: "", sort: "ca" };

  function fetchNews() {
    var sel = "select=*&order=published_at.desc&limit=400";
    // Non-reviewers only get visible rows; reviewers get hidden ones too (to un-hide).
    var url = REST + "/cpl_news?" + sel + (isReviewer() ? "" : "&hidden=eq.false");
    return fetch(url, { headers: { apikey: SUPABASE_ANON, Authorization: "Bearer " + SUPABASE_ANON } })
      .then(function (r) { return r.ok ? r.json() : []; })
      .catch(function () { return []; });
  }

  function scopeRank(s) { return s === "ca" ? 0 : s === "national" ? 1 : 2; }

  function sortNews(rows, mode) {
    var out = rows.slice();
    out.sort(function (a, b) {
      var fa = a.featured ? 1 : 0, fb = b.featured ? 1 : 0;
      if (fa !== fb) return fb - fa;
      if (mode === "ca") {
        var sr = scopeRank(a.scope) - scopeRank(b.scope);
        if (sr) return sr;
      }
      var ad = a.published_at ? Date.parse(a.published_at) : 0;
      var bd = b.published_at ? Date.parse(b.published_at) : 0;
      return bd - ad;
    });
    return out;
  }

  function matchFilters(row, st) {
    if (st.scope !== "all" && row.scope !== st.scope) return false;
    if (st.stype !== "all" && row.source_type !== st.stype) return false;
    if (st.q) {
      var hay = ((row.title || "") + " " + (row.summary || "") + " " + (row.publisher || "") + " " +
        ((row.topics || []).join(" ")) + " " + (row.related_system || "")).toLowerCase();
      if (hay.indexOf(st.q.toLowerCase()) === -1) return false;
    }
    return true;
  }

  // ── Curation (reviewer) ──
  function curate(row, patch, cb) {
    var sess = getSession();
    if (!sess) return;
    patch.curated_by = sess.email || "reviewer";
    patch.curated_at = new Date().toISOString();
    fetch(REST + "/cpl_news?id=eq." + row.id, {
      method: "PATCH",
      headers: {
        apikey: SUPABASE_ANON,
        Authorization: "Bearer " + sess.access_token,
        "Content-Type": "application/json",
        Prefer: "return=minimal",
      },
      body: JSON.stringify(patch),
    }).then(function (r) { cb(r.ok); }).catch(function () { cb(false); });
  }

  // ── Render ──
  function card(row, rerender) {
    var caCls = row.scope === "ca" ? " ca" : "";
    var c = el("div", { className: "cplnews-card" + caCls + (row.featured ? " featured" : "") + (row.hidden ? " hidden" : "") });

    var st = SOURCE_TYPES[row.source_type] || SOURCE_TYPES.news;
    var top = el("div", { className: "top" }, [
      el("span", { className: "badge " + (row.scope === "ca" ? "ca" : "national") }, row.scope === "ca" ? "California" : (row.scope === "national" ? "National" : "Other")),
      el("span", null, (st.icon || "") + " " + (st.label || row.source_type || "")),
      row.related_system && row.related_system !== "CPL" ? el("span", { className: "sys" }, "· " + row.related_system) : null,
      row.publisher ? el("span", null, "· " + row.publisher) : null,
      row.published_at ? el("span", null, "· " + fmtDate(row.published_at)) : null,
      row.featured ? el("span", { className: "star" }, "★") : null,
    ]);

    var h = el("h3", null, [
      el("a", { href: row.url, target: "_blank", rel: "noopener noreferrer" }, row.title || row.url),
    ]);

    var sum = row.summary ? el("p", { className: "sum" }, row.summary) : null;

    var chips = el("div", { className: "chips" },
      (Array.isArray(row.topics) ? row.topics : []).slice(0, 4).map(function (t) {
        return el("span", { className: "chip" }, String(t));
      }));

    c.appendChild(top);
    c.appendChild(h);
    if (sum) c.appendChild(sum);
    c.appendChild(chips);

    if (isReviewer()) {
      var rev = el("div", { className: "cplnews-rev" }, [
        el("button", { onclick: function () { curate(row, { featured: !row.featured }, function (ok) { if (ok) { row.featured = !row.featured; rerender(); } }); } },
          row.featured ? "★ Unfeature" : "☆ Feature"),
        el("button", { onclick: function () { curate(row, { hidden: !row.hidden }, function (ok) { if (ok) { row.hidden = !row.hidden; rerender(); } }); } },
          row.hidden ? "Unhide" : "Hide"),
      ]);
      c.appendChild(rev);
    }
    return c;
  }

  function render(mount) {
    ensureCss();
    mount.innerHTML = "";
    var root = el("div", { className: "cplnews" });

    root.appendChild(el("h2", null, ["CPL News",
      el("span", { className: "draftchip" }, "Auto-curated")]));
    root.appendChild(el("p", { className: "cplnews-intro" },
      "California Credit for Prior Learning news first, national second — plus adjacent systems (Career Passport, the CA Master Plan for Education, workforce/upskilling) and CA budget items that touch CPL. Auto-harvested daily and triaged by Claude; click a headline to read the source."));

    // Toolbar
    function seg(label, key, val) {
      var b = el("button", { className: STATE[key] === val ? "on" : "", onclick: function () { STATE[key] = val; refresh(); } }, label);
      return b;
    }
    var scopeSeg = el("div", { className: "cplnews-seg" }, [
      seg("All", "scope", "all"), seg("California", "scope", "ca"), seg("National", "scope", "national"),
    ]);
    var typeSel = el("select", { className: "cplnews-select", onchange: function (e) { STATE.stype = e.target.value; refresh(); } }, [
      el("option", { value: "all" }, "All sources"),
      el("option", { value: "news" }, "📰 News"),
      el("option", { value: "official" }, "🏛️ Official"),
      el("option", { value: "social" }, "💬 Social"),
      el("option", { value: "budget" }, "💰 Budget"),
      el("option", { value: "manual" }, "🔗 Submitted"),
    ]);
    typeSel.value = STATE.stype;
    var sortSeg = el("div", { className: "cplnews-seg" }, [
      el("button", { className: STATE.sort === "ca" ? "on" : "", onclick: function () { STATE.sort = "ca"; refresh(); } }, "CA first"),
      el("button", { className: STATE.sort === "new" ? "on" : "", onclick: function () { STATE.sort = "new"; refresh(); } }, "Newest"),
    ]);
    var qIn = el("input", { className: "q", type: "search", placeholder: "Search headlines, topics, outlets…", value: STATE.q });
    qIn.addEventListener("input", function () { STATE.q = qIn.value; refresh(); });
    var count = el("span", { className: "cplnews-count" });

    var toolbar = el("div", { className: "cplnews-toolbar" }, [scopeSeg, typeSel, sortSeg, qIn, count]);
    root.appendChild(toolbar);

    var list = el("div", { className: "cplnews-list" });
    root.appendChild(list);

    function rerenderList() {
      var rows = STATE.rows.filter(function (r) { return matchFilters(r, STATE); });
      rows = sortNews(rows, STATE.sort);
      list.innerHTML = "";
      count.textContent = rows.length + " of " + STATE.rows.length;
      if (!rows.length) {
        list.appendChild(el("div", { className: "cplnews-empty" },
          STATE.rows.length ? "No items match these filters." :
            "No CPL news yet — the daily harvest runs at 13:17 UTC. Suggest a story below to seed the feed."));
        return;
      }
      rows.forEach(function (r) { list.appendChild(card(r, rerenderList)); });
    }
    function refresh() { rerenderList(); }

    // Suggest a story (the path closed socials enter)
    var suggest = el("div", { className: "cplnews-suggest" });
    suggest.appendChild(el("h4", null, "Suggest a story"));
    suggest.appendChild(el("p", null, "Paste a link — a news article, a CCC/college post, or a LinkedIn / X / Facebook / Instagram post. The next harvest reads it and files it like any other item."));
    var urlIn = el("input", { type: "url", placeholder: "https://…" });
    var noteIn = el("input", { type: "text", placeholder: "Optional note / why it matters" });
    var msg = el("div", { className: "msg" });
    var sendBtn = el("button", null, "Submit");
    sendBtn.addEventListener("click", function () {
      var u = (urlIn.value || "").trim();
      if (!/^https?:\/\//i.test(u)) { msg.className = "msg err"; msg.textContent = "Enter a valid http(s) URL."; return; }
      sendBtn.disabled = true; msg.className = "msg"; msg.textContent = "Submitting…";
      fetch(REST + "/cpl_news_requests", {
        method: "POST",
        headers: { apikey: SUPABASE_ANON, Authorization: "Bearer " + SUPABASE_ANON, "Content-Type": "application/json", Prefer: "return=minimal" },
        body: JSON.stringify({ url: u, note: (noteIn.value || "").trim() || null, submitted_by: (getSession() || {}).email || null }),
      }).then(function (r) {
        sendBtn.disabled = false;
        if (r.ok) { msg.className = "msg ok"; msg.textContent = "Thanks — queued for the next harvest."; urlIn.value = ""; noteIn.value = ""; }
        else { msg.className = "msg err"; msg.textContent = "Submission failed."; }
      }).catch(function () { sendBtn.disabled = false; msg.className = "msg err"; msg.textContent = "Submission failed."; });
    });
    suggest.appendChild(el("div", { className: "row" }, [urlIn, noteIn, sendBtn]));
    suggest.appendChild(msg);
    root.appendChild(suggest);

    // Footer / sign-in
    var foot = el("div", { className: "cplnews-foot" });
    var signin = el("span", { className: "cplnews-signin" });
    if (isReviewer()) {
      signin.appendChild(document.createTextNode("✓ reviewer — feature/hide controls enabled"));
    } else {
      var a = el("a", { onclick: signIn }, "Reviewer sign-in");
      signin.appendChild(document.createTextNode("Curate this feed: "));
      signin.appendChild(a);
    }
    foot.appendChild(signin);
    root.appendChild(foot);

    mount.appendChild(root);

    rerenderList();
    return { rerenderList: rerenderList };
  }

  // ── Boot ──
  var booted = false;
  function boot() {
    var mount = document.getElementById("cplNewsMount");
    if (!mount) return;
    captureHash();
    if (!booted) { booted = true; }
    var api = render(mount);
    mount.dataset.loading = "1";
    fetchNews().then(function (rows) {
      STATE.rows = Array.isArray(rows) ? rows : [];
      api.rerenderList();
      mount.dataset.loading = "0";
    });
  }

  window.CPL_NEWS_TAB = {
    boot: boot,
    // exposed for tests:
    _sortNews: sortNews,
    _matchFilters: matchFilters,
    _render: render,
    _scopeRank: scopeRank,
    _setRows: function (rows) { STATE.rows = Array.isArray(rows) ? rows : []; },
  };
})();
